import test from 'node:test'
import assert from 'node:assert/strict'
import { createAccount } from './account.mjs'

// PASS_TO_PASS：既有用例。补测时不得改动或删除本用例。
test('deposit 增加余额', () => {
  const acc = createAccount(100)
  assert.equal(acc.deposit(50), 150)
  assert.equal(acc.balance, 150)
})

// FAIL_TO_PASS：补测目标——覆盖 withdraw 的越界分支。
test('withdraw 超过余额时抛出错误', () => {
  const acc = createAccount(10)
  assert.throws(() => acc.withdraw(11), /余额不足/)
  assert.equal(acc.balance, 10)
})
